# ------------------------------------------------------------------ #
#  Lifecycle / cleanup
# ------------------------------------------------------------------ #
def close(self, force: bool = True) -> None:
    """Shut down the terminal and reap the child process.

    Parameters
    ----------
    force:
        If *True* (default) send ``SIGHUP`` to the child's process group
        before waiting for it to exit.
    """
    if self._closed:
        return
    self._closed = True
    self._running = False

    # Signal the child process group to terminate.
    if force and self._pid is not None:
        try:
            # After pty.fork() the child is a session leader, so its
            # process-group id == its pid.
            os.killpg(self._pid, signal.SIGHUP)
        except OSError:
            pass

    # Stop the drain thread.
    if self._reader_thread is not None and self._reader_thread.is_alive():
        self._reader_thread.join(timeout=3)

    # Close the master fd (causes the child to get EIO / SIGHUP).
    if self._master_fd is not None:
        try:
            os.close(self._master_fd)
        except OSError:
            pass
        self._master_fd = None

    # Reap the child.
    if self._pid is not None and not self._child_reaped:
        deadline = time.monotonic() + 3
        while time.monotonic() < deadline:
            try:
                pid, status = os.waitpid(self._pid, os.WNOHANG)
            except OSError:
                break
            if pid != 0:
                self._exit_status = status
                self._child_reaped = True
                break
            time.sleep(0.05)
        if not self._child_reaped:
            # Last resort: SIGKILL and block-reap.
            try:
                os.killpg(self._pid, signal.SIGKILL)
            except OSError:
                pass
            try:
                pid, status = os.waitpid(self._pid, 0)
                self._exit_status = status
            except OSError:
                pass
            self._child_reaped = True
    self._pid = None

# ------------------------------------------------------------------ #
#  Context-manager support
# ------------------------------------------------------------------ #
def __enter__(self) -> "HeadlessTerminal":
    return self

def __exit__(self, exc_type, exc_val, exc_tb) -> None:
    self.close()

def __del__(self) -> None:
    try:
        self.close()
    except Exception:
        pass

# ------------------------------------------------------------------ #
#  Internals
# ------------------------------------------------------------------ #
def _write_all(self, data: bytes) -> None:
    """Write all of *data* to the master fd, retrying on EAGAIN."""
    fd = self._master_fd
    if fd is None:
        return
    offset = 0
    length = len(data)
    while offset < length:
        try:
            n = os.write(fd, data[offset:])
        except BlockingIOError:
            # Slave input buffer full - give the child time to read.
            time.sleep(_WRITE_RETRY_DELAY)
            continue
        except InterruptedError:
            continue
        except OSError:
            # EIO -> child has exited / PTY gone.
            break
        if n <= 0:
            break
        offset += n

def _drain_loop(self) -> None:
    """Background thread: continuously read child output to avoid deadlock."""
    fd = self._master_fd
    if fd is None:
        return
    while self._running:
        try:
            readable, _, _ = select.select([fd], [], [], _POLL_TIMEOUT)
        except (OSError, ValueError):
            break
        if not readable:
            continue
        try:
            chunk = os.read(fd, _READ_SIZE)
        except BlockingIOError:
            continue
        except InterruptedError:
            continue
        except OSError as exc:
            # EIO on Linux means the slave was closed (child exited).
            if exc.errno in (errno.EIO, errno.EBADF):
                break
            continue
        if not chunk:
            # EOF - child closed the slave.
            break
        with self._buffer_lock:
            self._output_buffer.extend(chunk)
        self._output_ready.set()

# -- low-level helpers ------------------------------------------------ #
@staticmethod
def _set_nonblocking(fd: int) -> None:
    flags = fcntl.fcntl(fd, fcntl.F_GETFL)
    fcntl.fcntl(fd, fcntl.F_SETFL, flags | os.O_NONBLOCK)

@staticmethod
def _set_winsize(fd: int, rows: int, cols: int) -> None:
    """Set the PTY window size via the ``TIOCSWINSZ`` ioctl."""
    try:
        winsize = struct.pack("HHHH", rows, cols, 0, 0)
        fcntl.ioctl(fd, termios.TIOCSWINSZ, winsize)
    except OSError:
        pass
